ee:variables.ee:set-variable:
%dw 2.0
// Booking search POST /v3/checkpropertyavailability body for the rooms to book, built only from vars.bookingRequest.
// The multi-room body of get-multi-room-rates.xml (one apartmentList entry per room, noOfRooms = their count, guest
// counts as strings, childAges passed through), plus the caller's voucherCode, which T-08 sends and T-04 does not.
// memberId stays "" (anonymous MVP); messageId is the correlation ID.
output application/json skipNullOn="everywhere"

var r = vars.bookingRequest default {}
var rooms = r.apartmentList default []
---
{
	messageId: vars.traceId,
	memberId: "",
	language: r.language,
	currencyCode: r.currency default p('property.currency'),
	promoCorpCode: "",
	propertyListing: false,
	isModifyJourney: false,
	// An array, one code: propertyListing false allows exactly one.
	propertyCode: [r.propertyCode],
	checkinDate: r.checkin,
	checkoutDate: r.checkout,
	voucherCode: r.voucherCode default "",
	noOfRooms: sizeOf(rooms),
	// The guests of all rooms together, as the multi-room body.
	noOfadults: (r.adults default 1) as String,
	noOfchildren: (r.children default 0) as String,
	minPrice: "",
	maxPrice: "",
	perNightRate: true,
	apartmentList: rooms map ((a) -> {
		childAges: a.childAges default [],
		noOfadults: (a.noOfadults default 1) as String,
		noOfchildren: (a.noOfchildren default 0) as String
	}),
	// Booking search's minBaseRate fails (500) when userCountry is empty.
	userCountry: p('default.userCountry') default "SG",
	isExcludePriceStartFrom: false,
	// Rate plans are tagged MOBILE / WEB; "mcp" matches none.
	channel: "mobile"
}
